package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"reflect"
)

type N struct {
	T     string `json:"t"`
	Owns  int    `json:"owns"`
	File  string `json:"file"`
	SL    int    `json:"sl"`
	EL    int    `json:"el"`
	SO    int    `json:"so"`
	EO    int    `json:"eo"`
}

func main() {
	var all []N
	for _, fn := range os.Args[1:] {
		fset := token.NewFileSet()
		f, err := parser.ParseFile(fset, fn, nil, 0)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			continue
		}
		var seq []N
		var stack []int
		ast.Inspect(f, func(n ast.Node) bool {
			if n == nil {
				idx := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				seq[idx].Owns = len(seq) - idx - 1
				return false
			}
			if id, ok := n.(*ast.Ident); ok && id == f.Name {
				return false
			}
			t := reflect.TypeOf(n).Elem().Name()
			seq = append(seq, N{T: t, File: fn, SL: fset.Position(n.Pos()).Line, EL: fset.Position(n.End()).Line, SO: fset.Position(n.Pos()).Offset, EO: fset.Position(n.End()).Offset})
			stack = append(stack, len(seq)-1)
			return true
		})
		all = append(all, seq...)
	}
	json.NewEncoder(os.Stdout).Encode(all)
}
EOF
