import sys, json, subprocess, itertools

class Node:
    __slots__=("start","end","children","link","leafpos","depth","id")
    def __init__(self, start, end):
        self.start=start; self.end=end  # edge label [start,end) ; end None => leaf (to current end)
        self.children=[]  # list of (token, Node) in insertion order
        self.link=None
        self.leafpos=None
    def child(self, tok):
        for t,c in self.children:
            if t==tok: return c
        return None
    def set_child(self, tok, node):
        for i,(t,c) in enumerate(self.children):
            if t==tok:
                self.children[i]=(tok,node); return
        self.children.append((tok,node))

def build(seq):
    # Ukkonen's algorithm; seq is list of hashable tokens incl. unique terminator
    root=Node(-1,-1)
    n=len(seq)
    def elen(node, cur):
        return (node.end if node.end is not None else cur+1) - node.start
    active_node=root; active_edge=0; active_len=0; remainder=0
    leaves=[]
    for i,tok in enumerate(seq):
        remainder+=1
        last_new=None
        while remainder>0:
            if active_len==0: active_edge=i
            nxt=active_node.child(seq[active_edge])
            if nxt is None:
                leaf=Node(i,None); leaf.leafpos=i-remainder+1
                active_node.set_child(seq[active_edge], leaf)
                if last_new is not None: last_new.link=active_node; last_new=None
            else:
                # walk down
                if active_len>=elen(nxt,i):
                    active_edge+=elen(nxt,i); active_len-=elen(nxt,i); active_node=nxt
                    continue
                if seq[nxt.start+active_len]==tok:
                    active_len+=1
                    if last_new is not None: last_new.link=active_node; last_new=None
                    break
                # split
                split=Node(nxt.start, nxt.start+active_len)
                active_node.set_child(seq[active_edge], split)
                nxt.start+=active_len
                split.children.append((seq[nxt.start], nxt))
                leaf=Node(i,None); leaf.leafpos=i-remainder+1
                split.children.append((tok,leaf))
                if last_new is not None: last_new.link=split
                last_new=split
            remainder-=1
            if active_node is root and active_len>0:
                active_len-=1; active_edge=i-remainder+1
            else:
                active_node=active_node.link if active_node.link is not None else root
    # compute depths
    def setd(node, d):
        node.depth=d
        for t,c in node.children:
            setd(c, d+elen(c, n-1))
    setd(root,0)
    return root

def leaves_of(node):
    if not node.children: return [node.leafpos]
    r=[]
    for t,c in node.children: r+=leaves_of(c)
    return r

def matches(root, thr, order="pre"):
    out=[]
    def walk(node):
        if not node.children: return
        if node.depth>=thr and node is not root and order=="pre":
            out.append((leaves_of(node), node.depth))
        for t,c in node.children: walk(c)
        if node.depth>=thr and node is not root and order=="post":
            out.append((leaves_of(node), node.depth))
    walk(root)
    return out
