def load(files):
    out=subprocess.run(["/tmp/dump/dump"]+files, capture_output=True, text=True).stdout
    return json.loads(out)

def units(seq, start, length, thr, descend=True, pick="largest"):
    runs=[]; cur=[]
    i=0
    while i<length:
        n=seq[start+i]; size=n["owns"]+1
        if i+size>length:
            if cur: runs.append(cur); cur=[]
            if descend: i+=1
            else: break
        elif size<thr:
            if cur: runs.append(cur); cur=[]
            i+=size
        else:
            cur.append(i); i+=size
    if cur: runs.append(cur)
    if not runs: return []
    if pick=="largest":
        best=None
        for r in runs:
            tot=sum(seq[start+j]["owns"]+1 for j in r)
            if best is None or tot>best[0]: best=(tot,r)
        return best[1]
    if pick=="last": return runs[-1]
    if pick=="first": return runs[0]

def real(dirpath, thr, extra=[]):
    out=subprocess.run(["/workspace/executable","-t",str(thr)]+extra, cwd=dirpath, capture_output=True, text=True).stdout
    groups=[]; cur=None
    for line in out.splitlines():
        if line.startswith("found "):
            cur=[]; groups.append(cur)
        elif line.startswith("  "):
            f,rest=line.strip().split(":")
            a,b=rest.split(",")
            cur.append((f,int(a),int(b)))
    return groups

def simulate(files, thr, order="pre", descend=True, pick="largest", dedup="none", term="global"):
    seq=load(files)
    toks=[n["t"] for n in seq]
    if term=="global":
        toks=toks+["$"]
    root=build(toks)
    ms=matches(root, thr, order)
    groups=[]
    for ps, ln in ms:
        cl=[]
        for p in ps:
            if p>=len(seq): continue
            u=units(seq,p,min(ln,len(seq)-p),thr,descend,pick)
            if not u: continue
            first=seq[p+u[0]]; last=seq[p+u[-1]]
            if first["file"]!=last["file"]: continue
            cl.append((first["file"],first["so"],last["eo"],first["sl"],last["el"],p))
        groups.append(cl)
    return seq, groups

def fmt(groups):
    return [sorted((f.split("/")[-1],sl,el) for (f,so,eo,sl,el,p) in g) for g in groups]
EOF
