		"fnv64a": func(b []byte) []byte { h := fnv.New64a(); h.Write(b); return h.Sum(nil) },
		"crc32":  func(b []byte) []byte { h := crc32.NewIEEE(); h.Write(b); return h.Sum(nil) },
	}
	encs := map[string]func([]int) []byte{
		"byte":   func(t []int) []byte { b := make([]byte, len(t)); for i, v := range t { b[i] = byte(v) }; return b },
		"dec":    func(t []int) []byte { var b bytes.Buffer; for _, v := range t { b.WriteString(strconv.Itoa(v)) }; return b.Bytes() },
		"decsp":  func(t []int) []byte { var b bytes.Buffer; for i, v := range t { if i > 0 { b.WriteByte(' ') }; b.WriteString(strconv.Itoa(v)) }; return b.Bytes() },
		"decnl":  func(t []int) []byte { var b bytes.Buffer; for _, v := range t { b.WriteString(strconv.Itoa(v)); b.WriteByte('\n') }; return b.Bytes() },
		"deccm":  func(t []int) []byte { var b bytes.Buffer; for i, v := range t { if i > 0 { b.WriteByte(',') }; b.WriteString(strconv.Itoa(v)) }; return b.Bytes() },
		"golist": func(t []int) []byte { var b bytes.Buffer; b.WriteByte('['); for i, v := range t { if i > 0 { b.WriteByte(' ') }; b.WriteString(strconv.Itoa(v)) }; b.WriteByte(']'); return b.Bytes() },
		"le32":   func(t []int) []byte { var b bytes.Buffer; for _, v := range t { binary.Write(&b, binary.LittleEndian, int32(v)) }; return b.Bytes() },
		"le64":   func(t []int) []byte { var b bytes.Buffer; for _, v := range t { binary.Write(&b, binary.LittleEndian, int64(v)) }; return b.Bytes() },
	}
	var wg sync.WaitGroup
	var mu sync.Mutex
	out, _ := os.Create("/tmp/brute/results2.txt")
	max := 100
	if len(os.Args) > 1 { max, _ = strconv.Atoi(os.Args[1]) }
	for hname, h := range hashes {
		for ename, enc := range encs {
			for _, desc := range []bool{false, true} {
				wg.Add(1)
				go func(hname string, h hfn, ename string, enc func([]int) []byte, desc bool) {
					defer wg.Done()
					empty := h(enc([]int{}))
					count := 0
					for E := 0; E < max; E++ {
						for C := 0; C < max; C++ {
							if C == E { continue }
							for I := 0; I < max; I++ {
								if I == E || I == C { continue }
								for B := 0; B < max; B++ {
									if B == E || B == C || B == I { continue }
									ok := true
									for k := 2; k <= 24 && ok; k++ {
										t := make([]int, 0, 5*k)
										for j := 0; j < k; j++ { t = append(t, E, C, I, B, B) }
										t = t[:len(t)-1]
										hv := h(enc(t))
										gf := bytes.Compare(hv, empty) < 0
										if desc { gf = !gf }
										if gf != fp[k] { ok = false }
									}
									if ok {
										count++
										mu.Lock()
										fmt.Fprintf(out, "MATCH %s %s desc=%v E=%d C=%d I=%d B=%d\n", hname, ename, desc, E, C, I, B)
										mu.Unlock()
									}
								}
							}
						}
					}
					mu.Lock()
					fmt.Fprintf(out, "done %s %s desc=%v matches=%d\n", hname, ename, desc, count)
					mu.Unlock()
				}(hname, h, ename, enc, desc)
			}
		}
	}
	wg.Wait()
}
